 const {character,boot}=useKairo();const [detail,setDetail]=useState<any>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[pinName,setPinName]=useState(''),[pinBody,setPinBody]=useState(''),[pinDate,setPinDate]=useState(''),[pinKind,setPinKind]=useState('note'),[calendarEvent,setCalendarEvent]=useState('manual'),[structureId,setStructureId]=useState(''),[verifying,setVerifying]=useState(false),[verified,setVerified]=useState<any>(null),[verifyError,setVerifyError]=useState('');
 useEffect(()=>{let live=true;api('/universe/systems/'+system.system_id+'?character='+character).then(d=>{if(live)setDetail(d);}).catch(e=>{if(live)setError(errorMessage(e));});return()=>{live=false;};},[system.system_id,character]);
